<?php declare(strict_types=1);require_once __DIR__.'/includes/store.php';$number=trim((string)($_GET['order']??''));$s=$pdo->prepare('SELECT order_number,total_amount,payment_status,status FROM orders WHERE order_number=? LIMIT 1');$s->execute([$number]);$order=$s->fetch();if(!$order){http_response_code(404);exit('Order not found.');}$pageTitle='Order received';require __DIR__.'/includes/header.php';?><section class="container py-5"><div class="card border-0 shadow-sm p-4 p-md-5 mx-auto" style="max-width:720px"><div class="text-success display-5">✓</div><h1 class="h2">Thank you. Your order was received.</h1><p>Your order reference is <strong><?=e($order['order_number'])?></strong>.</p><p>Total: <strong><?=money($order['total_amount'])?></strong>. Payment status: <span class="badge text-bg-warning"><?=e($order['payment_status'])?></span></p><p>Your order remains pending until the store reviews it. Keep your M-Pesa confirmation message in case staff need to verify payment.</p><div class="d-flex gap-2 flex-wrap"><a class="btn btn-primary" href="profile.php">My account / orders</a><a class="btn btn-outline-primary" href="shop.php">Continue shopping</a></div></div></section><?php require __DIR__.'/includes/footer.php';?>
